import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { chipGeometry } from './brand.js';

// The home page of awana.kvbchurch.org (printer/, the "Public website") draws
// the lobby's four stepped chips as inline SVG in printer/components/Lobby.tsx.
// They are generated by this app's own chipGeometry() around Paytone One's
// measured widths (the SVG textLengths are those widths, so a chip's plate
// hugs its words): if that geometry changes, this fails until the page's chips
// are regenerated, never hand-edited. (Its other rules, the kit's faces and the
// no-Awana-art rules, are checked by printer/scripts/test-about-page.cjs.)
const tsx = readFileSync(resolve(__dirname, '../../../printer/components/Lobby.tsx'), 'utf8');

describe('the stepped chips on the home page are the lobby\'s own geometry around Paytone One\'s widths', () => {
  const chips = [...tsx.matchAll(/<svg className="cid-step"[\s\S]*?<\/svg>/g)].map(([svg]) => {
    const texts = [...svg.matchAll(/<text [^>]*fontSize="([^"]+)" textLength="([^"]+)"[^>]*>([^<]*)<\/text>/g)]
      .map(([, size, width, text]) => ({ size: Number(size), width: Number(width), text }));
    return { svg, plate: svg.match(/className="cid-step__plate" d="([^"]+)"/)?.[1] ?? '', texts };
  });
  const nums = (d) => d.match(/-?\d+(?:\.\d+)?/g).map(Number);
  // The proportions live in brand.js; a 1-em label and value read them back.
  const unit = chipGeometry(1, 1);

  it('the section carries the four chips its screens show', () => {
    expect(chips.map((c) => c.texts.map((t) => t.text).join(' '))).toEqual([
      'CLEAR SKIES 58°', 'WAITING 3', 'RIGHT NOW 8:05', 'RIGHT NOW 8:05',
    ]);
  });

  it.each([0, 1, 2, 3])('chip %i draws the label and value at the current sizes on a plate that hugs them', (i) => {
    const { plate, texts } = chips[i];
    const [label, value] = texts;
    expect(label.size).toBe(unit.label.size);
    expect(value.size).toBe(unit.value.size);
    // Rebuild the plate from the widths the text is pinned to.
    const g = chipGeometry(label.width / unit.label.size, value.width / unit.value.size);
    const got = nums(plate);
    const want = nums(g.d);
    expect(got.length).toBe(want.length);
    got.forEach((n, k) => expect(Math.abs(n - want[k])).toBeLessThan(0.003));
  });
});
